@Test
public void savesValueOnShutdown() {
    AtomicLong savedValue = new AtomicLong(validInitialValue());
    SpaceUsageSource source = mock(SpaceUsageSource.class);
    final long usedSpace = 4L;
    when(source.getUsedSpace()).thenReturn(usedSpace, 5L, 6L);
    SpaceUsageCheckParams params = paramsBuilder(savedValue).withSource(source).build();
    ScheduledFuture<?> future = mock(ScheduledFuture.class);
    ScheduledExecutorService executor = sameThreadExecutorWithoutDelay(future);
    CachingSpaceUsageSource subject = new CachingSpaceUsageSource(params, executor);
    subject.start();
    subject.shutdown();
    assertEquals(usedSpace, savedValue.get(), "value should have been saved to file");
    assertEquals(usedSpace, subject.getUsedSpace(), "no further updates from source expected");
    verify(future).cancel(true);
    verify(executor).shutdown();
}

