}

@Test
public void testContainerRocksDB() throws StorageContainerException, RocksDBException {
    closeContainer();
    keyValueContainer = new KeyValueContainer(keyValueContainerData, CONF);
    keyValueContainer.create(volumeSet, volumeChoosingPolicy, scmId);
    try (ReferenceCountedDB db = BlockUtils.getDB(keyValueContainerData, CONF)) {
        RDBStore store = (RDBStore) db.getStore().getStore();
        long defaultCacheSize = 64 * OzoneConsts.MB;
        long cacheSize = Long.parseLong(store.getProperty("rocksdb.block-cache-capacity"));
        Assert.assertEquals(defaultCacheSize, cacheSize);
        for (ColumnFamilyHandle handle : store.getColumnFamilyHandles()) {
            cacheSize = Long.parseLong(store.getProperty(handle, "rocksdb.block-cache-capacity"));
            Assert.assertEquals(defaultCacheSize, cacheSize);
        }
    }
}

