    // Create Container 1
    keyValueContainer.create(volumeSet, volumeChoosingPolicy, scmId);
    DatanodeDBProfile outProfile1;
    try (ReferenceCountedDB db1 = BlockUtils.getDB(keyValueContainer.getContainerData(), CONF)) {
