@Test
public void testDownloadAndImportReplicatorFailure() {
    ReplicationSupervisor supervisor = new ReplicationSupervisor(set, null, mutableReplicator, newDirectExecutorService());
    // Mock to fetch an exception in the importContainer method.
    SimpleContainerDownloader moc = Mockito.mock(SimpleContainerDownloader.class);
    CompletableFuture<Path> res = new CompletableFuture<>();
    res.complete(Paths.get("file:/tmp/no-such-file"));
    Mockito.when(moc.getContainerDataFromReplicas(Mockito.anyLong(), Mockito.anyList())).thenReturn(res);
