    new DeletedBlockLogImpl(conf, containerManager, scm.getScmHAManager().getRatisServer(), scm.getScmMetadataStore().getDeletedBlocksTXTable(), scmHADBTransactionBuffer, scm.getScmContext(), scm.getSequenceIdGen(), metrics);
