    //given
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.setStorageSize(OZONE_DATANODE_RATIS_VOLUME_FREE_SPACE_MIN, 10, StorageUnit.MB);
    List<DatanodeDetails> datanodes = new ArrayList<>();
    for (int i = 0; i < 3; i++) {
        datanodes.add(MockDatanodeDetails.randomDatanodeDetails());
    }
    NodeManager mockNodeManager = Mockito.mock(NodeManager.class);
    SCMContainerPlacementRandom scmContainerPlacementRandom = new SCMContainerPlacementRandom(mockNodeManager, conf, null, true, null);
    ContainerPlacementStatus status = scmContainerPlacementRandom.validateContainerPlacement(datanodes, 3);
    assertTrue(status.isPolicySatisfied());
    assertEquals(0, status.misReplicationCount());
    status = scmContainerPlacementRandom.validateContainerPlacement(new ArrayList<DatanodeDetails>(), 3);
    assertFalse(status.isPolicySatisfied());
    // Only expect 1 more replica to give us one rack on this policy.
    assertEquals(1, status.misReplicationCount(), 3);
