    conf.setTimeDuration(HddsConfigKeys.HDDS_SCM_WAIT_TIME_AFTER_SAFE_MODE_EXIT, 0, TimeUnit.SECONDS);
    conf.setInt(ScmConfigKeys.OZONE_DATANODE_PIPELINE_LIMIT, 2);
    conf.setStorageSize(OZONE_DATANODE_RATIS_VOLUME_FREE_SPACE_MIN, 10, StorageUnit.MB);
    storageDir = GenericTestUtils.getTempPath(TestDeadNodeHandler.class.getSimpleName() + UUID.randomUUID());
    conf.set(HddsConfigKeys.OZONE_METADATA_DIRS, storageDir);
    eventQueue = new EventQueue();
    scm = TestUtils.getScm(conf);
    nodeManager = (SCMNodeManager) scm.getScmNodeManager();
    pipelineManager = (PipelineManagerV2Impl) scm.getPipelineManager();
    PipelineProvider mockRatisProvider = new MockRatisPipelineProvider(nodeManager, pipelineManager.getStateManager(), conf);
    pipelineManager.setPipelineProvider(RATIS, mockRatisProvider);
    containerManager = scm.getContainerManager();
    deadNodeHandler = new DeadNodeHandler(nodeManager, Mockito.mock(PipelineManager.class), containerManager);
    eventQueue.addHandler(SCMEvents.DEAD_NODE, deadNodeHandler);
    publisher = Mockito.mock(EventPublisher.class);
    nodeReportHandler = new NodeReportHandler(nodeManager);
}

@Test
public void testOnMessage() throws Exception {
    //GIVEN
    DatanodeDetails datanode1 = MockDatanodeDetails.randomDatanodeDetails();
    DatanodeDetails datanode2 = MockDatanodeDetails.randomDatanodeDetails();
    DatanodeDetails datanode3 = MockDatanodeDetails.randomDatanodeDetails();
    String storagePath = GenericTestUtils.getRandomizedTempPath().concat("/data-" + datanode1.getUuidString());
    String metaStoragePath = GenericTestUtils.getRandomizedTempPath().concat("/metadata-" + datanode1.getUuidString());
    StorageReportProto storageOne = TestUtils.createStorageReport(datanode1.getUuid(), storagePath, 100 * OzoneConsts.TB, 10 * OzoneConsts.TB, 90 * OzoneConsts.TB, null);
    MetadataStorageReportProto metaStorageOne = TestUtils.createMetadataStorageReport(metaStoragePath, 100 * OzoneConsts.GB, 10 * OzoneConsts.GB, 90 * OzoneConsts.GB, null);
    // Exit safemode, as otherwise the safemode precheck will prevent pipelines
    // from getting created. Due to how this test is wired up, safemode will
    // not exit when the DNs are registered directly with the node manager.
    scm.exitSafeMode();
    // Standalone pipeline now excludes the nodes which are already used,
    // is the a proper behavior. Adding 9 datanodes for now to make the
    // test case happy.
    nodeManager.register(datanode1, TestUtils.createNodeReport(Arrays.asList(storageOne), Arrays.asList(metaStorageOne)), null);
    nodeManager.register(datanode2, TestUtils.createNodeReport(Arrays.asList(storageOne), Arrays.asList(metaStorageOne)), null);
    nodeManager.register(datanode3, TestUtils.createNodeReport(Arrays.asList(storageOne), Arrays.asList(metaStorageOne)), null);
    nodeManager.register(MockDatanodeDetails.randomDatanodeDetails(), TestUtils.createNodeReport(Arrays.asList(storageOne), Arrays.asList(metaStorageOne)), null);
    nodeManager.register(MockDatanodeDetails.randomDatanodeDetails(), TestUtils.createNodeReport(Arrays.asList(storageOne), Arrays.asList(metaStorageOne)), null);
    nodeManager.register(MockDatanodeDetails.randomDatanodeDetails(), TestUtils.createNodeReport(Arrays.asList(storageOne), Arrays.asList(metaStorageOne)), null);
    nodeManager.register(MockDatanodeDetails.randomDatanodeDetails(), TestUtils.createNodeReport(Arrays.asList(storageOne), Arrays.asList(metaStorageOne)), null);
    nodeManager.register(MockDatanodeDetails.randomDatanodeDetails(), TestUtils.createNodeReport(Arrays.asList(storageOne), Arrays.asList(metaStorageOne)), null);
    nodeManager.register(MockDatanodeDetails.randomDatanodeDetails(), TestUtils.createNodeReport(Arrays.asList(storageOne), Arrays.asList(metaStorageOne)), null);
    LambdaTestUtils.await(120000, 1000, () -> {
        return pipelineManager.getPipelines(new RatisReplicationConfig(THREE)).size() > 3;
    });
    TestUtils.openAllRatisPipelines(pipelineManager);
    ContainerInfo container1 = TestUtils.allocateContainer(containerManager);
    ContainerInfo container2 = TestUtils.allocateContainer(containerManager);
    ContainerInfo container3 = TestUtils.allocateContainer(containerManager);
    ContainerInfo container4 = TestUtils.allocateContainer(containerManager);
    registerContainers(datanode1, container1, container2, container4);
    registerContainers(datanode2, container1, container2);
    registerContainers(datanode3, container3);
    registerReplicas(containerManager, container1, datanode1, datanode2);
    registerReplicas(containerManager, container2, datanode1, datanode2);
    registerReplicas(containerManager, container3, datanode3);
    registerReplicas(containerManager, container4, datanode1);
    TestUtils.closeContainer(containerManager, container1.containerID());
    TestUtils.closeContainer(containerManager, container2.containerID());
    TestUtils.quasiCloseContainer(containerManager, container3.containerID());
    // First set the node to IN_MAINTENANCE and ensure the container replicas
    // are not removed on the dead event
    nodeManager.setNodeOperationalState(datanode1, HddsProtos.NodeOperationalState.IN_MAINTENANCE);
    deadNodeHandler.onMessage(datanode1, publisher);
    Set<ContainerReplica> container1Replicas = containerManager.getContainerReplicas(ContainerID.valueOf(container1.getContainerID()));
    Assert.assertEquals(2, container1Replicas.size());
    Set<ContainerReplica> container2Replicas = containerManager.getContainerReplicas(ContainerID.valueOf(container2.getContainerID()));
    Assert.assertEquals(2, container2Replicas.size());
    Set<ContainerReplica> container3Replicas = containerManager.getContainerReplicas(ContainerID.valueOf(container3.getContainerID()));
    Assert.assertEquals(1, container3Replicas.size());
    // Now set the node to anything other than IN_MAINTENANCE and the relevant
    // replicas should be removed
    nodeManager.setNodeOperationalState(datanode1, HddsProtos.NodeOperationalState.IN_SERVICE);
    deadNodeHandler.onMessage(datanode1, publisher);
    container1Replicas = containerManager.getContainerReplicas(ContainerID.valueOf(container1.getContainerID()));
    Assert.assertEquals(1, container1Replicas.size());
    Assert.assertEquals(datanode2, container1Replicas.iterator().next().getDatanodeDetails());
    container2Replicas = containerManager.getContainerReplicas(ContainerID.valueOf(container2.getContainerID()));
    Assert.assertEquals(1, container2Replicas.size());
    Assert.assertEquals(datanode2, container2Replicas.iterator().next().getDatanodeDetails());
    container3Replicas = containerManager.getContainerReplicas(ContainerID.valueOf(container3.getContainerID()));
    Assert.assertEquals(1, container3Replicas.size());
    Assert.assertEquals(datanode3, container3Replicas.iterator().next().getDatanodeDetails());
}

