@Test
public void testValidateAndUpdateCacheWithDirectoryAlreadyExists() throws Exception {
    String volumeName = "vol1";
    String bucketName = "bucket1";
    List<String> dirs = new ArrayList<String>();
    String keyName = createDirKey(dirs, 3);
    // Add volume and bucket entries to DB.
    TestOMRequestUtils.addVolumeAndBucketToDB(volumeName, bucketName, omMetadataManager);
    String bucketKey = omMetadataManager.getBucketKey(volumeName, bucketName);
    OmBucketInfo omBucketInfo = omMetadataManager.getBucketTable().get(bucketKey);
    long bucketID = omBucketInfo.getObjectID();
    // bucketID is the parent
    long parentID = bucketID;
    // add all the directories into DirectoryTable
    for (int indx = 0; indx < dirs.size(); indx++) {
        long objID = 100 + indx;
        long txnID = 5000 + indx;
        // for index=0, parentID is bucketID
        OmDirectoryInfo omDirInfo = TestOMRequestUtils.createOmDirectoryInfo(dirs.get(indx), objID, parentID);
        TestOMRequestUtils.addDirKeyToDirTable(false, omDirInfo, txnID, omMetadataManager);
        parentID = omDirInfo.getObjectID();
    }
    OMRequest omRequest = createDirectoryRequest(volumeName, bucketName, keyName);
    OMDirectoryCreateRequestWithFSO omDirCreateReqFSO = new OMDirectoryCreateRequestWithFSO(omRequest);
    OMRequest modifiedOmReq = omDirCreateReqFSO.preExecute(ozoneManager);
    omDirCreateReqFSO = new OMDirectoryCreateRequestWithFSO(modifiedOmReq);
    OMClientResponse omClientResponse = omDirCreateReqFSO.validateAndUpdateCache(ozoneManager, 100L, ozoneManagerDoubleBufferHelper);
    Assert.assertTrue(omClientResponse.getOMResponse().getStatus() == OzoneManagerProtocolProtos.Status.DIRECTORY_ALREADY_EXISTS);
    Assert.assertEquals("Wrong OM numKeys metrics", 0, ozoneManager.getMetrics().getNumKeys());
    // Key should exist in DB and doesn't added to cache.
    verifyDirectoriesInDB(dirs, bucketID);
    verifyDirectoriesNotInCache(dirs, bucketID);
}

/**
 * Case: File exists with the same name as the requested directory.
 * Say, requested to createDir '/a/b/c' and there is a file exists with
 * same name.
 */
@Test
public void testValidateAndUpdateCacheWithFilesInPath() throws Exception {
    String volumeName = "vol1";
    String bucketName = "bucket1";
    List<String> dirs = new ArrayList<String>();
    String keyName = createDirKey(dirs, 3);
    // Add volume and bucket entries to DB.
    TestOMRequestUtils.addVolumeAndBucketToDB(volumeName, bucketName, omMetadataManager);
    String bucketKey = omMetadataManager.getBucketKey(volumeName, bucketName);
    OmBucketInfo omBucketInfo = omMetadataManager.getBucketTable().get(bucketKey);
    long parentID = omBucketInfo.getObjectID();
    // add all the parent directories into DirectoryTable. This won't create
    // the leaf node and this will be used in CreateDirectoryReq.
    for (int indx = 0; indx < dirs.size() - 1; indx++) {
        long objID = 100 + indx;
        long txnID = 5000 + indx;
        // for index=0, parentID is bucketID
        OmDirectoryInfo omDirInfo = TestOMRequestUtils.createOmDirectoryInfo(dirs.get(indx), objID, parentID);
        TestOMRequestUtils.addDirKeyToDirTable(false, omDirInfo, txnID, omMetadataManager);
        parentID = omDirInfo.getObjectID();
    }
    long objID = parentID + 100;
    long txnID = 50000;
    // Add a file into the FileTable, this is to simulate "file exists" check.
    OmKeyInfo omKeyInfo = TestOMRequestUtils.createOmKeyInfo(volumeName, bucketName, keyName, HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.THREE, objID++);
    String ozoneFileName = parentID + "/" + dirs.get(dirs.size() - 1);
    ++txnID;
    omMetadataManager.getKeyTable().addCacheEntry(new CacheKey<>(ozoneFileName), new CacheValue<>(Optional.of(omKeyInfo), txnID));
    omMetadataManager.getKeyTable().put(ozoneFileName, omKeyInfo);
    OMRequest omRequest = createDirectoryRequest(volumeName, bucketName, keyName);
    OMDirectoryCreateRequestWithFSO omDirCreateReqFSO = new OMDirectoryCreateRequestWithFSO(omRequest);
    OMRequest modifiedOmReq = omDirCreateReqFSO.preExecute(ozoneManager);
    omDirCreateReqFSO = new OMDirectoryCreateRequestWithFSO(modifiedOmReq);
    OMClientResponse omClientResponse = omDirCreateReqFSO.validateAndUpdateCache(ozoneManager, 100L, ozoneManagerDoubleBufferHelper);
    Assert.assertTrue(omClientResponse.getOMResponse().getStatus() == OzoneManagerProtocolProtos.Status.FILE_ALREADY_EXISTS);
    Assert.assertEquals("Wrong OM numKeys metrics", 0, ozoneManager.getMetrics().getNumKeys());
    // Key should not exist in DB
    Assert.assertNotNull(omMetadataManager.getKeyTable().get(ozoneFileName));
    // Key should not exist in DB
    Assert.assertEquals("Wrong directories count!", 3, omMetadataManager.getDirectoryTable().getEstimatedKeyCount());
}

/**
 * Case: File exists in the given path.
 * Say, requested to createDir '/a/b/c/d' and there is a file '/a/b' exists
 * in the given path.
 */
@Test
public void testValidateAndUpdateCacheWithFileExistsInGivenPath() throws Exception {
    String volumeName = "vol1";
    String bucketName = "bucket1";
    List<String> dirs = new ArrayList<String>();
    String keyName = createDirKey(dirs, 3);
    // Add volume and bucket entries to DB.
    TestOMRequestUtils.addVolumeAndBucketToDB(volumeName, bucketName, omMetadataManager);
    String bucketKey = omMetadataManager.getBucketKey(volumeName, bucketName);
    OmBucketInfo omBucketInfo = omMetadataManager.getBucketTable().get(bucketKey);
    long parentID = omBucketInfo.getObjectID();
    long objID = parentID + 100;
    long txnID = 5000;
    // for index=0, parentID is bucketID
    OmDirectoryInfo omDirInfo = TestOMRequestUtils.createOmDirectoryInfo(dirs.get(0), objID++, parentID);
    TestOMRequestUtils.addDirKeyToDirTable(true, omDirInfo, txnID, omMetadataManager);
    parentID = omDirInfo.getObjectID();
    // Add a key in second level.
    OmKeyInfo omKeyInfo = TestOMRequestUtils.createOmKeyInfo(volumeName, bucketName, keyName, HddsProtos.ReplicationType.RATIS, HddsProtos.ReplicationFactor.THREE, objID);
    String ozoneKey = parentID + "/" + dirs.get(1);
    ++txnID;
    omMetadataManager.getKeyTable().addCacheEntry(new CacheKey<>(ozoneKey), new CacheValue<>(Optional.of(omKeyInfo), txnID));
    omMetadataManager.getKeyTable().put(ozoneKey, omKeyInfo);
    OMRequest omRequest = createDirectoryRequest(volumeName, bucketName, keyName);
    OMDirectoryCreateRequestWithFSO omDirCreateReqFSO = new OMDirectoryCreateRequestWithFSO(omRequest);
    OMRequest modifiedOmReq = omDirCreateReqFSO.preExecute(ozoneManager);
    omDirCreateReqFSO = new OMDirectoryCreateRequestWithFSO(modifiedOmReq);
    OMClientResponse omClientResponse = omDirCreateReqFSO.validateAndUpdateCache(ozoneManager, 100L, ozoneManagerDoubleBufferHelper);
    Assert.assertTrue("Invalid response code:" + omClientResponse.getOMResponse().getStatus(), omClientResponse.getOMResponse().getStatus() == OzoneManagerProtocolProtos.Status.FILE_ALREADY_EXISTS);
    Assert.assertEquals("Wrong OM numKeys metrics", 0, ozoneManager.getMetrics().getNumKeys());
    // Key should not exist in DB
    Assert.assertTrue(omMetadataManager.getKeyTable().get(ozoneKey) != null);
    // Key should not exist in DB
    Assert.assertEquals("Wrong directories count!", 1, omMetadataManager.getDirectoryTable().getEstimatedKeyCount());
}

