     * validateAndUpdateCache(). */
    long renewTime = 1000L;
    when(secretManager.updateToken(any(Token.class), any(OzoneTokenIdentifier.class), anyLong())).thenReturn(renewTime);
    OMClientResponse clientResponse = setValidateAndUpdateCache();
    Optional<Long> responseRenewTime = Optional.fromNullable(omMetadataManager.getDelegationTokenTable().get(identifier));
