    fileSizeCountTask.process(omUpdateEventBatch);
    // Verify 2 keys are in correct bins.
    assertEquals(2, fileCountBySizeDao.count());
    Record3<String, String, Long> recordToFind = dslContext.newRecord(FILE_COUNT_BY_SIZE.VOLUME, FILE_COUNT_BY_SIZE.BUCKET, FILE_COUNT_BY_SIZE.FILE_SIZE).value1("vol1").value2("bucket1").value3(2048L);
    assertEquals(1L, fileCountBySizeDao.findById(recordToFind).getCount().longValue());
    // file size upper bound for 10000L is 16384L (next highest power of 2)
    recordToFind.value3(16384L);
    assertEquals(1L, fileCountBySizeDao.findById(recordToFind).getCount().longValue());
    // Add new key.
    OmKeyInfo newKey = mock(OmKeyInfo.class);
    given(newKey.getVolumeName()).willReturn("vol1");
    given(newKey.getBucketName()).willReturn("bucket1");
    given(newKey.getKeyName()).willReturn("newKey");
    // Bin 0
    given(newKey.getDataSize()).willReturn(1000L);
    OMDBUpdateEvent putEvent = new OMUpdateEventBuilder().setAction(PUT).setKey("newKey").setValue(newKey).setTable(OmMetadataManagerImpl.KEY_TABLE).build();
    // Update existing key.
    OmKeyInfo updatedKey = mock(OmKeyInfo.class);
    given(updatedKey.getVolumeName()).willReturn("vol1");
    given(updatedKey.getBucketName()).willReturn("bucket1");
    given(updatedKey.getKeyName()).willReturn("updatedKey");
    // Bin 6
    given(updatedKey.getDataSize()).willReturn(50000L);
    OMDBUpdateEvent updateEvent = new OMUpdateEventBuilder().setAction(UPDATE).setKey("updatedKey").setValue(updatedKey).setOldValue(toBeUpdatedKey).setTable(OmMetadataManagerImpl.KEY_TABLE).build();
    // Delete another existing key.
    OMDBUpdateEvent deleteEvent = new OMUpdateEventBuilder().setAction(DELETE).setKey("deletedKey").setValue(toBeDeletedKey).setTable(OmMetadataManagerImpl.KEY_TABLE).build();
    omUpdateEventBatch = new OMUpdateEventBatch(Arrays.asList(updateEvent, putEvent, deleteEvent));
    fileSizeCountTask.process(omUpdateEventBatch);
    assertEquals(4, fileCountBySizeDao.count());
    recordToFind.value3(1024L);
    assertEquals(1, fileCountBySizeDao.findById(recordToFind).getCount().longValue());
    recordToFind.value3(2048L);
    assertEquals(0, fileCountBySizeDao.findById(recordToFind).getCount().longValue());
    recordToFind.value3(16384L);
    assertEquals(0, fileCountBySizeDao.findById(recordToFind).getCount().longValue());
    recordToFind.value3(65536L);
    assertEquals(1, fileCountBySizeDao.findById(recordToFind).getCount().longValue());
}

